git checkout -q -b fix/issue-12-double-discount && cat > src/cart.js <<'EOF'
// Cart total in yen. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied once,
// after the customer's discount.
//
// Rounding: a total with a customer discount drops any fraction of a yen.
// Without a customer discount the total is rounded as before (half a yen up) —
// wholesale invoices (src/invoice.js, #7) depend on that matching the price list.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const discounted = subtotal * (1 - discount) * (1 - bulk);
  if (discount === 0) return Math.round(discounted);
  return Math.floor(dropFloatNoise(discounted));
}

// 1000 * (1 - 0.9) is 99.99999999999997 in floating point; without this,
// flooring would charge 99 instead of 100.
function dropFloatNoise(amount) {
  return Math.round(amount * 1e6) / 1e6;
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
cat >> tests/cart.test.js <<'EOF'

// Issue #12: the customer's discount must be applied only once.
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10000 * 0.9 * 0.95
});

test('a discounted total drops fractions of a yen', () => {
  assert.equal(total([{ price: 15, qty: 1 }], 0.1), 13); // 13.5
  assert.equal(total([{ price: 11, qty: 1 }], 0.1), 9); // 9.9
});

test('flooring is not thrown off by floating-point noise', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.9), 100); // 99.99999999999997 in floats
  assert.equal(total([{ price: 100, qty: 1 }], 0.3), 70);
});
EOF
